INSERT INTO delay_reason_codes
  (delay_code, reason_name, violation, responsibility, units, source, note, full_description)
VALUES
  ('1', 'Неприем поезда ж.д. станцией назначения на территории России по причинам, зависящим от грузополучателей, владельцев или пользователей путей необщего пользования', NULL, 'Грузоотправитель/Грузополучатель/Оператор ПС', 'Грузополучатель', 'методика №2040/р (Распоряжение №85/р 2025)', 'Учитывается как одна из причин нарушения срока доставки (методика 2040/р).', 'Неприем поезда железнодорожной станцией ОАО "РЖД" назначения на территории России по причинам, зависящим от грузополучателей, владельцев или пользователей путей необщего пользования'),
  ('2', 'Неприем поезда пограничным переходом с  третьими странами, государствами СНГ или инфраструктурой общего пользования др. владельца', NULL, 'Третьи лица / Сторонние организации', 'ЦД, ЦСС', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Неприем поезда пограничным переходом с "третьими" странами, государствами СНГ или инфраструктурой общего пользования другого владельца'),
  ('3', 'Превышение нормативного времени на таможенный, санитарный досмотр', NULL, 'Третьи лица / Сторонние организации', '', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Превышение нормативного времени на таможенный, санитарный досмотр'),
  ('4', 'Остановка от движения поездов с грузами, перевозимыми в прямом смешанном сообщении при ответственности перевозчика др. транспорта', NULL, 'Грузоотправитель/Грузополучатель/Оператор ПС', 'Грузоотправитель, Оператор ПС', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отстановка от движения поездов с грузами, перевозимыми в прямом смешанном сообщении при ответственности перевозчика другого вида транспорта'),
  ('5', 'Оказание в пути следования услуг по временному размещению собств. (аренд) подвижного состава на ж.д. путях общего пользования ( в соотв. с закл. договором)', NULL, 'Грузоотправитель/Грузополучатель/Оператор ПС', 'Грузополучатель', 'методика №2040/р (Распоряжение №85/р 2025)', 'Платная услуга по договору о временном размещении подвижного состава; при корректном оформлении документов на нарушение срока доставки не влияет.', 'Оказание в пути следования услуг по временному размещению собственного (арендованного) подвижного состава на железнодорожных путях общего пользования (в соответствии с заключенным договором)'),
  ('6', 'Оказание услуг по накоплению судовой партии, согласно заключенному с грузовладельцем договору', NULL, 'Грузоотправитель/Грузополучатель/Оператор ПС', 'Грузополучатель', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Оказание услуг по накоплению судовой партии, согласно заключенному с грузовладельцем договору'),
  ('11', 'Превышение установ. размеров движения', NULL, 'Перевозчик', 'ЦД', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Превышение установленных размеров движения'),
  ('13', 'Неправильная регулировка движения поездов ДНЦ', NULL, 'Перевозчик', 'ЦД', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Неправильная регулировка движения поездов диспетчером'),
  ('21', 'Отказы тех. средств, наход. в ведении дирекции тяги', NULL, 'Перевозчик', 'ЦТ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отказы технических средств, находящихся в ведении дирекции тяги - структурного подразделения Центральной дирекции тяги - филиала ОАО "РЖД"'),
  ('22', 'Отсутствие или ожидание лок-ва перевозчика из-за недосодержания экспл. парка лок-ов к установленному плану по видам движения', NULL, 'Перевозчик', 'ЦТ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отсутствие или ожидание локомотива перевозчика из-за недосодержания эксплуатируемого парка локомотивов к установленному плану по видам движения'),
  ('23', 'Отсутствие или ожидание локомотивной бригады перевозчика', NULL, 'Перевозчик', 'ЦТ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отсутствие или ожидание локомотивной бригады перевозчика'),
  ('24', 'Несвоевременная выдача локомотива', NULL, 'Перевозчик', 'ЦТ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Несвоевременная выдача локомотива'),
  ('25', 'Оказание помощи пасс и приг поездам, задержанным по причине неисправности локомотива', NULL, 'Перевозчик', 'ЦТ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Оказание помощи пассажирским и пригородным поездам, задержанным по причине неисправности локомотива'),
  ('31', 'Отказы тех. средств, наход. в ведении дирекции по ремонту тягового п.с.', NULL, 'Перевозчик', 'ЦТВР', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отказы технических средств, находящихся в ведении дирекции по ремонту тягового подвижного состава'),
  ('35', 'Отказы тех. средств, наход. в ведении дирекции по ремонту пути.', NULL, 'Перевозчик', 'ЦДРП', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отказы технических средств, находящихся в ведении дирекции по ремонту пути - структурного подразделения Центральной дирекции по ремонту пути - филиала ОАО "РЖД"'),
  ('36', 'Передержка плановых «окон», предоставление неплановых «окон», нарушение технологии работ в «окно» по вине дирекции по ремонту пути.', NULL, 'Перевозчик', 'ЦДРП', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Передержка проводимых плановых технологических "окон", предоставление неплановых технологических "окон", нарушение технологии работ в технологическое "окно" по вине работников дирекции по ремонту пути'),
  ('41', 'Занятость неисправными вагонами станц. Путей, не предназначенных по технологии работы станции для дислокации вагонов в ожидании ТР', NULL, 'Перевозчик', 'ЦДИ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Занятость неисправными вагонами станционных путей, не предназначенных по технологии работы станции для дислокации вагонов в ожидании текущего ремонта'),
  ('42', 'Превышение нормы на ТО составов', NULL, 'Перевозчик', 'ЦДИ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Превышение нормы на техническое обслуживание составов'),
  ('43', 'Отказы тех. средств, находящихся в ведении дирекции инфраструктуры', NULL, 'Перевозчик', 'ЦДИ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отказы технических средств, находящихся в ведении дирекции инфраструктуры - структурного подразделения Центральной дирекции инфраструктуры - филиала ОАО "РЖД"'),
  ('44', 'Несвоевременная очистка путей, стрелок от загрязнение, снега, ликвидация последствий паводков.', NULL, 'Перевозчик', 'ЦДИ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Несвоевременная очистка путей, стрелок от загрязнения, снега, ликвидация последствий паводков'),
  ('45', 'Наезд поездов и ман. составов на автотранспортные ср-ва, посторонних лиц, ДТП на переездах.', NULL, 'Перевозчик', 'ЦДИ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Наезд поездов и маневровых составов на автотранспортные средства, посторонних лиц, ДТП на переездах'),
  ('46', 'Ограничение пропускной способности участов, станций при проведении «окон» не предусмотренных план-графиком', NULL, 'Перевозчик', 'ЦДИ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Ограничение пропускной способности участков, станций при проведении технологических "окон", не предусмотренных план-графиком'),
  ('47', 'Задержка вызванная передержкой технологического «окна»', NULL, 'Перевозчик', 'ЦДИ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Задержка, вызванная передержкой технологического "окна"'),
  ('48', 'Задержка, вызванная нарушением технологии производства технологического "окна"', NULL, 'Перевозчик', 'ЦДИ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Задержка, вызванная нарушением технологии производства технологического "окна"'),
  ('49', 'Нарушение параметров содержания объектов инфр-ры, требующее выдачи неграфикового предупреждения, повлекшее отстановку поезда от движения', NULL, 'Перевозчик', 'ЦДИ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Нарушение параметров содержания объектов инфраструктуры, требующее выдачи неграфикового предупреждения, повлекшее отстановку поезда от движения'),
  ('51', 'Отсутствие или понижение напряжения в контактной сети, в том числе из-за откл. Электроэнергии нетранспортными организациями', NULL, 'Перевозчик', 'ТЭ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отсутствие или понижение напряжения в контактной сети, в том числе из-за отключения электроэнергии нетранспортными организациями'),
  ('52', 'Отказы тех. ср-тв, находящихся в ведении ТЭ', NULL, 'Перевозчик', 'ТЭ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отказы технических средств, находящихся в ведении ТЭ'),
  ('53', 'Ограничение пропускной способности уч-ов, ст-ий при предоставлении технологических «окон» ТЭ, не предусмотренных план-графиком', NULL, 'Перевозчик', 'ТЭ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Ограничение пропускной способности участков, станций при предоставлении технологических "окон" ТЭ, не предусмотренных планом-графиком'),
  ('54', 'Нарушение работниками ТЭ технологии производства работ в технологическое «окна»', NULL, 'Перевозчик', 'ТЭ', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Нарушение работниками ТЭ технологии производства работ в технологическое "окно"'),
  ('61', 'Отказы тех. средств, находящихся в ведении дирекции МВПС', NULL, 'Перевозчик', 'ЦМВПС', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отказы технических средств, находящихся в ведении дирекции моторвагонного подвижного состава - структурного подразделения Центральной дирекции моторвагонного подвижного состава - филиала ОАО "РЖД"'),
  ('63', 'Занятость путей общего пользования в местах проведения погрузочно-разгрузочных работ силами производственных участков ДМ', NULL, 'Перевозчик', 'ЦДС', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Занятость путей общего пользования в местах проведения погрузочно-разгрузочных работ силами производственных участков ДМ'),
  ('71', 'Отказы тех. средств, находящихся в ведении дирекции связи', NULL, 'Перевозчик', 'ЦСС', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отказы технических средств, находящихся в ведении структурных подразделений дирекции связи - структурного подразделения Центральной станции связи - филиала ОАО "РЖД"'),
  ('81', 'Неравномерная погрузка в адрес одного получателя', NULL, 'Перевозчик', 'ЦФТО', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Неравномерная погрузка в адрес одного получателя'),
  ('82', 'Погрузка сверх установленного тех. плана', NULL, 'Перевозчик', 'ЦФТО', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Погрузка сверх установленного технического плана'),
  ('91', 'Стихийные бедствия, при которых администрацией данной территории объявляется чрезвычайно положение, техногенные катастрофы', NULL, 'Третьи лица / Сторонние организации', '', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Стихийные бедствия, при которых администрацией данной территории объявляется чрезвычайное положение, техногенные катастрофы'),
  ('92', 'Угроза террористических актов, незаконного вмешательства в деятельность ж.д. транспорта', NULL, 'Третьи лица / Сторонние организации', '', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Угроза террористических актов, незаконное вмешательство в деятельность ж.д. транспорта'),
  ('93', 'Отсутствие (ожидание) локомотива, не принадлежащего перевозчику', NULL, 'Третьи лица / Сторонние организации', '', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Отсутствие (ожидание) локомотива, не принадлежащего перевозчику'),
  ('94', 'Неприем порожних собственных полувагонов, подсылаемых на Западно-Сибирскую ж.д.', NULL, 'Третьи лица / Сторонние организации', '', 'методика №2040/р (Распоряжение №85/р 2025)', '', 'Неприем порожних собственных полувагонов, подсылаемых на Западно-Сибирскую железную дорогу'),
  ('95', 'Невозможность приема станцией перегрузки контейнеров, следующих с перегрузкой в пути следования из одного типа вагонов в другой. (* Данный код вводится после утверждения и реализации нормативного документа ОАО "РЖД", регламентирующего вопросы организации перевозки контейнеров со сменой подвижного состава в пути следования, о вводе в действие причастные будут дополнительно проинформированы.").', NULL, 'Третьи лица / Сторонние организации', '', 'методика №2040/р (Распоряжение №85/р 2025)', '', '')
